(* VM fast paths for self-contained binary-number operations.

   The checker admits a C operation only after its checked body matches the
   exact build-pinned serialization of the canonical Corelib body. Runtime
   closure selection is structural-body equality plus closure identity, never
   constant-name equality. The C implementations below need no transparent
   definition other than the closure they replace, so an [Opaque] dependency
   cannot change their bytecode semantics. *)

open Declarations

type operation =
  | Pos_compare_cont
  | Pos_eqb

let enabled = Sys.getenv_opt "ROCQ_VM_FASTBIN" = Some "1"
let trace = Sys.getenv_opt "ROCQ_VM_FASTBIN_TRACE" = Some "1"

let anchors = [
  "Corelib.BinNums.PosDef.Pos.compare_cont", Pos_compare_cont;
  "Corelib.BinNums.PosDef.Pos.eqb", Pos_eqb;
]

let references : (operation, Constr.t) Hashtbl.t = Hashtbl.create (List.length anchors)

let id = function
  | Pos_compare_cont -> 0
  | Pos_eqb -> 1

let arity = function
  | Pos_compare_cont -> 3
  | Pos_eqb -> 2

external register_closure : Vmvalues.values -> int -> int -> unit = "rocq_vmfast_register"

let marshal_hex value =
  let bytes = Marshal.to_string value [Marshal.No_sharing] in
  let out = Bytes.create (String.length bytes * 2) in
  String.iteri (fun i c ->
      let encoded = Printf.sprintf "%02x" (Char.code c) in
      Bytes.blit_string encoded 0 out (i * 2) 2)
    bytes;
  Bytes.unsafe_to_string out

let fixed_serialization = function
  | Pos_compare_cont ->
    ""
  | Pos_eqb ->
    "8495a6be000004c300000000000004b4000004649ea0a0904140b090a090236571624090b6a0902170409ba0a090b090a02742696e4e756d73a0274e756d62657273a027436f72656c69624028706f736974697665022c3b5f4240a08080b6a0902171409ba0a090b090a02742696e4e756d73a0274e756d62657273a027436f" ^
    "72656c69624028706f736974697665022c3b5f4240a080809ba0a090b090a029446174617479706573a024496e6974a027436f72656c69624024626f6f6c0210a9f8d840a0808090b7a0902170409ba0a090b090a02742696e4e756d73a0274e756d62657273a027436f72656c69624028706f736974697665022c3b5f4240a0" ^
    "8080b7a0902171409ba0a090b090a02742696e4e756d73a0274e756d62657273a027436f72656c69624028706f736974697665022c3b5f4240a08080fdd0a090b090a02742696e4e756d73a0274e756d62657273a027436f72656c69624028706f736974697665022c3b5f424040b0414140b04141409044a0808080a0a090a0" ^
    "902170409ba0a090b090a029446174617479706573a024496e6974a027436f72656c69624024626f6f6c0210a9f8d840a0808040409042b0a090a090217040fdd0a090b090a02742696e4e756d73a0274e756d62657273a027436f72656c69624028706f736974697665022c3b5f424040b0414140b04141409044a0808080a0" ^
    "a090a0902171409ba0a090b090a029446174617479706573a024496e6974a027436f72656c69624024626f6f6c0210a9f8d840a0808040409042b0a090a090217140a99045a090429041a090a090227030409ca0a0a090b090a029446174617479706573a024496e6974a027436f72656c69624024626f6f6c0210a9f8d84042" ^
    "a08080a0809ca0a0a090b090a029446174617479706573a024496e6974a027436f72656c69624024626f6f6c0210a9f8d84042a08080a090a090217040fdd0a090b090a02742696e4e756d73a0274e756d62657273a027436f72656c69624028706f736974697665022c3b5f424040b0414140b04141409044a0808080a0a090" ^
